import React, {useState} from 'react'
import {useDispatch, useSelector} from "react-redux"
import {Button, ConfigProvider, FloatButton, Popover, Select, Typography} from "antd"
import {RetweetOutlined} from "@ant-design/icons"

import {bookActions, selectRepeatState} from "../../state/book-reducer"
import "./floating-menu.css"

const GOLD = "#906720"
const CIRCLE_SIZE = "3.75rem"

function slokaOptions(count) {
  return Array.from({length: count}, (_, index) => ({
    value: index + 1,
    label: String(index + 1),
  }))
}

function RepeatPanel({count, repeat, dispatch}) {
  const options = slokaOptions(count)

  return (
    <div className="repeat-panel-circles">
      <Typography.Text className="repeat-glass-label block text-center mb-3">
        Repeat
      </Typography.Text>

      <div className="flex justify-center mb-4">
        <Button
          className="repeat-glass-circle repeat-glass-btn"
          type={repeat.oneToggle ? "primary" : "default"}
          onClick={() => dispatch(bookActions.one())}
        >
          1
        </Button>
      </div>

      <div className="flex items-center justify-center gap-3">
        <Select
          className="repeat-glass-circle repeat-glass-select"
          style={{width: CIRCLE_SIZE}}
          value={repeat.fromSloka}
          options={options}
          suffixIcon={null}
          popupMatchSelectWidth={false}
          onChange={val => dispatch(bookActions.repeatFrom(val))}
        />
        <Typography.Text className="repeat-glass-to">–</Typography.Text>
        <Select
          className="repeat-glass-circle repeat-glass-select"
          style={{width: CIRCLE_SIZE}}
          value={repeat.toSloka}
          options={options}
          suffixIcon={null}
          popupMatchSelectWidth={false}
          onChange={val => dispatch(bookActions.repeatTo(val))}
        />
        <Button
          className="repeat-glass-circle repeat-glass-btn repeat-glass-btn-ab"
          type={repeat.manyToggle ? "primary" : "default"}
          onClick={() => dispatch(bookActions.many())}
        >
          A–B
        </Button>
      </div>
    </div>
  )
}

function RangeLabel({from, to}) {
  const fromStr = String(from)
  const toStr = String(to)
  const stacked = fromStr.length >= 2 && toStr.length >= 2

  if (stacked) {
    return (
      <span className="repeat-float-range repeat-float-range-stacked">
        <span>{fromStr}</span>
        <span className="repeat-float-range-dash">–</span>
        <span>{toStr}</span>
      </span>
    )
  }

  return <span className="repeat-float-range">{fromStr}–{toStr}</span>
}

export function FloatingMenu({count}) {
  const [open, setOpen] = useState(false)
  const repeat = useSelector(selectRepeatState)
  const dispatch = useDispatch()

  const isActive = repeat.oneToggle || repeat.manyToggle

  const floatIcon = repeat.manyToggle
    ? <RangeLabel from={repeat.fromSloka} to={repeat.toSloka}/>
    : <RetweetOutlined/>

  const rangeLayout = repeat.manyToggle &&
    String(repeat.fromSloka).length >= 2 &&
    String(repeat.toSloka).length >= 2
      ? " has-range-stacked"
      : " has-range"

  return (
    <ConfigProvider theme={{
      token: {
        colorPrimary: GOLD,
        borderRadius: 999,
        controlHeight: 60,
        fontSize: 17,
      },
    }}>
      <Popover
        open={open}
        onOpenChange={setOpen}
        trigger="click"
        placement="topRight"
        arrow={false}
        overlayClassName="repeat-glass-popover"
        content={
          <RepeatPanel count={count} repeat={repeat} dispatch={dispatch}/>
        }
      >
        <FloatButton
          shape="circle"
          icon={floatIcon}
          className={`repeat-float-glass${isActive ? " is-active" : ""}${repeat.manyToggle ? rangeLayout : ""}`}
        />
      </Popover>
    </ConfigProvider>
  )
}
