import {useEffect, useState} from "react";
import {useDispatch, useSelector} from "react-redux"
import {Card, Button} from "antd";

import {bookActions, selectActiveSloka} from "../../state/book-reducer"
import {formatSlokaLines, getAudioSeekSeconds, isInViewport} from "../../utils/util"
import '../../assets/sloka.css'

export function Sloka(props) {
  const {
    chapNum, slokaNum,
    slokam, meaning,
    audioUrl,
  } = props

  const activeSloka = useSelector(selectActiveSloka)
  const dispatch = useDispatch()

  const [collapseNum, setCollapseNum] = useState(null);

  useEffect(() => {
    const active = activeSloka
    if (!active) {
      window.scrollTo(0, 0);
      return
    }

    // if not seen in screen, scroll..
    const activeElement = document.querySelector("#slokam" + active)
    if (activeElement) {
      if (!isInViewport(activeElement)) {
        const prevElement = document.querySelector(active === 1 ? "#bookTitle" : `#slokam${active - 1}`)
        prevElement.scrollIntoView({behavior: "smooth"})
      }
    }
  }, [activeSloka])

  const toggleSlokaMeaning = (e, slokaNumber) => {
    e.stopPropagation()
    setCollapseNum(slokaNumber === collapseNum ? 0 : slokaNumber)
  }

  const playPause = slokaClicked => {
    if (!activeSloka || activeSloka !== slokaClicked) {
      dispatch(bookActions.activeSloka(slokaClicked))
    } else {
      song.paused ? song.play() : song.pause()
      return
    }

    // set sloka window & play
    document.querySelector("#songSource").src = audioUrl
    song.currentTime = getAudioSeekSeconds(audioUrl)
    song.play()
  }

  return <Card
    id={"slokam" + slokaNum}
    size="small"
    className="sloka-card"
    bodyStyle={{padding: 0}}
  >
    {/*--------- 1. Slokam ---------*/}
    <div className="sloka-lines" onClick={() => playPause(slokaNum)}>
      <Button className="sloka-meaning-button"
              style={{border: activeSloka === slokaNum ? "2px solid #906720" : 0}}
              onClick={e => toggleSlokaMeaning(e, slokaNum)}>
        {chapNum + "." + slokaNum}
      </Button>
      {formatSlokaLines(slokam).map((line, key) =>
        <span key={key}>
          {line} <br/>
        </span>
      )}
    </div>
    <div style={{display: collapseNum === slokaNum ? "flex" : "none", padding: "0.6rem"}}>
      <div className="flex-grow w-0">
        {/*--------- 2. Word Meanings ---------*/}
        <div className="sloka-meaning">
          {meaning && meaning.meaning}
        </div>
        {/*--------- 3. Slokam Meaning ---------*/}
        <div className="sloka-translation">
          {meaning && meaning.translation}
        </div>
      </div>
    </div>
  </Card>;
}
