//
// --------- Content API ---------
//

import yaml from "yaml"

import {contentPath} from "../config"

// ---- Paths in PUBLIC folder ----

const PATHS = {
  slokas: contentPath('/content/gita/slokas/slokas.yaml'),
  meaning: contentPath('/content/gita/slokas/slokas-meaning.yaml'),
  audioTime: contentPath('/content/gita/audio/audio-time.yaml'),

  vsnSlokasOrig: contentPath('/content/vishnu-sahasra-namam/slokas.yaml'),
  vsnSlokas: contentPath('/content/vishnu-sahasra-namam/slokas-visvas.yaml'),
  vsnSlokasMeaningOrig: contentPath('/content/vishnu-sahasra-namam/slokas-meaning.yaml'),
  vsnSlokasMeaning: contentPath('/content/vishnu-sahasra-namam/slokas-meaning-exam.yaml'),
};

const AUDIO = {
  "1-5": contentPath('/content/gita/audio/chapter-01-05.mp3'),
  "6-12": contentPath('/content/gita/audio/chapter-06-12.mp3'),
  "13-18": contentPath('/content/gita/audio/chapter-13-18.mp3'),
};

// --------------Exported--------------

export const fetcher = {
  slokas: fetchData(PATHS.slokas),
  audioTime: fetchData(PATHS.audioTime),
  meaning: fetchData(PATHS.meaning),

  vsnSlokas: fetchData(PATHS.vsnSlokas),
  vsnSlokasMeaning: fetchData(PATHS.vsnSlokasMeaning),
};

export const getAudioUrl = (chapter) => {
  if ([1, 2, 3, 4, 5].includes(chapter)) return AUDIO["1-5"];
  if ([6, 7, 8, 9, 10, 11, 12].includes(chapter)) return AUDIO["6-12"];
  if ([13, 14, 15, 16, 17, 18].includes(chapter)) return AUDIO["13-18"];
  return null;
};

// --------------Private--------------
async function fetchData(path) {
  const res = await fetch(path);
  if (!res.ok) {
    throw new Error(`Failed to fetch ${path}: ${res.status} ${res.statusText}`);
  }
  const text = await res.text();
  return yaml.parse(text);
}
