import React from "react"
import {Link, useLocation} from "react-router-dom";

export function AppHeader() {
  const location = useLocation();

  const title = location.pathname === "/vishnu-sahasra-namam"
    ? "శ్రీ విష్ణు సహస్రనామ స్తోత్రం"
    : "భగవద్గీత";

  return (
    <>
      <div className={"h-2"}></div>
      <Link id="bookTitle"
            to="/"
            className="mx-auto justify-content-evenly no-underline text-[2rem] text-[palegoldenrod]">
        {title}
      </Link>
      <div className={"h-2"}></div>
    </>
  )
}
