const normalizeBasePath = path => {
  if (!path) {
    return '/bhagavad-gita'
  }
  return path.replace(/\/$/, '')
}

/** Deploy base path — from CRA `PUBLIC_URL` or `.env` `REACT_APP_BASE_NAME`. */
export const BASE_PATH = normalizeBasePath(
  process.env.PUBLIC_URL || process.env.REACT_APP_BASE_NAME
)

/** Absolute path under the public folder, e.g. `/bhagavad-gita/content/...`. */
export const contentPath = relativePath => {
  const path = relativePath.startsWith('/') ? relativePath : `/${relativePath}`
  return `${BASE_PATH}${path}`
}
